V = "Apploye"
CS = "Vendor case study"
LG = "Vendor testimonial/logo"
B = "https://apploye.com/customer-stories/"
HP = "https://apploye.com/"
def r(name, slug, since, size, industry, summary, contacts=None, conf=100, status="CURRENT", notes="", signals=""):
    return dict(company_name=name, industry=industry, employee_count=size, employee_count_source_url=B+slug, vendor=V, evidence_type=CS,
        evidence_summary=summary + f" Apploye customer since {since} (per story).", source_url=B+slug, source_publication_date="2026",
        second_source_url="https://apploye.com/customer-stories", status=status,
        status_reason="Live named Apploye customer story listed in 2026 (sitemap lastmod 2026-08-25)", confidence_score=conf,
        contacts=contacts or [], workforce_signals=signals, notes=notes)
def logo(name, domain="", industry="", country="", contacts=None, li="", emp="", empsrc="", notes=""):
    return dict(company_name=name, company_domain=domain, industry=industry, hq_country=country, employee_count=emp, employee_count_source_url=empsrc,
        vendor=V, evidence_type=LG, evidence_summary="Company logo shown in Apploye homepage 'Trusted by' logo strip (2026).",
        source_url=HP, source_publication_date="2026", status="POSSIBLE", status_reason="Logo only on vendor homepage", confidence_score=55,
        contacts=contacts or [], company_linkedin=li, notes=notes)
